export default function HomePage() {
  const containerRef = useRef(null);

  useEffect(() => {
    // 1. Add html classes
    document.documentElement.classList.add('cs-inverse', 'booting');
    const timer = setTimeout(() => {
      document.documentElement.classList.remove('booting');
    }, 7000);

    // 2. Inject exact CSS
    const styleEl = document.createElement('style');
    styleEl.id = 'home-page-style';
    styleEl.textContent = HOME_CSS;
    document.head.appendChild(styleEl);

    // 3. Run script
    let cleanup;
    try {
      cleanup = runHomeScript();
    } catch (e) {
      console.warn('Home script execution:', e);
    }

    return () => {
      clearTimeout(timer);
      document.documentElement.classList.remove('cs-inverse', 'booting');
      if (document.head.contains(styleEl)) {
        document.head.removeChild(styleEl);
      }
      if (cleanup && typeof cleanup === 'function') {
        cleanup();
      }
    };
  }, []);

  return (
    <div
      ref={containerRef}
      className="home-vanilla-wrapper"
      dangerouslySetInnerHTML={{ __html: HOME_MARKUP }}
    />
  );
}
